// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./IClaimModule.sol";

interface IERC20 {
    function balanceOf(address owner) external view returns (uint256);
}

/**
 * @notice Claim: caller holds at least `minBalance` of the ERC20 token
 */
contract ERC20DAOClaimModule is IClaimModule {
    function verify(address user, bytes calldata data) external view override returns (bool) {
        (address token, uint256 minBalance) = abi.decode(data, (address, uint256));
        return IERC20(token).balanceOf(user) >= minBalance;
    }
}

contracts/ERC721ClaimModule.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./IClaimModule.sol";

interface IERC721 {
    function balanceOf(address owner) external view returns (uint256);
}

/**
 * @notice Claim: caller owns at least one token of the given ERC721 contract
 */
contract ERC721ClaimModule is IClaimModule {
    function verify(address user, bytes calldata data) external view override returns (bool) {
        address nftContract = abi.decode(data, (address));
        return IERC721(nftContract).balanceOf(user) > 0;
    }
}

contracts/IClaimModule.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title IClaimModule
 * @notice Interface for selective disclosure claim verifiers
 */
interface IClaimModule {
    /**
     * @notice Verifies whether a user satisfies a claim
     * @param user Wallet address making the claim
     * @param data ABI-encoded claim parameters (module-specific schema)
     */
    function verify(address user, bytes calldata data) external view returns (bool);
}

contracts/MyDAORegistryAdapter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./IClaimModule.sol";

/**
 * @dev Example DAO-specific registry interface
 */
interface IMyDAORegistry {
    function isActiveMember(address user) external view returns (bool);
}

/**
 * @notice Claim: caller is an active member according to this DAO's registry
 * @dev Adapter is intentionally per-DAO to keep trust assumptions explicit
 */
contract MyDAORegistryAdapter is IClaimModule {
    address public immutable registry;

    constructor(address _registry) {
        registry = _registry;
    }

    function verify(address user, bytes calldata) external view override returns (bool) {
        return IMyDAORegistry(registry).isActiveMember(user);
    }
}

contracts/WalletAgeClaimModule.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./IClaimModule.sol";

/**
 * @notice Claim: wallet age in days is at least the provided threshold
 * @dev Off-chain systems supply the derived age; on-chain module is pure for hackathon-safety
 */
contract WalletAgeClaimModule is IClaimModule {
    function verify(address, bytes calldata data) external pure override returns (bool) {
        uint256 walletAgeDays = abi.decode(data, (uint256));
        return walletAgeDays >= 90;
    }
}

